function getRytrTranslation(key, lang) {
  if (rytrTranslations[lang] && rytrTranslations[lang][key]) {
    return rytrTranslations[lang][key];
  }
  if (rytrTranslations.en && rytrTranslations.en[key]) {
    return rytrTranslations.en[key];
  }
  return null;
}

function applyRytrTranslations(lang) {
  
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.rytr.') || key.startsWith('review.common.'))) {
      const translation = getRytrTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyRytrTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyRytrTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyRytrTranslations(currentLang);
}


